    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use contrapunk_harmony::{HarmonyMode, Key};

    fn fixture() -> Arc<WorldState> {
        let transport = Transport::new(48_000);
        let engine = Arc::new(Mutex::new(HarmonyEngine::new(
            Key::C,
            HarmonyMode::PassThrough,
        )));
        WorldState::new(transport, engine)
    }

    #[test]
