        let w = fixture();
        assert!(w.held_inputs.lock().unwrap().is_empty());
        assert!(w.sounding_voices.lock().unwrap().is_empty());
        assert_eq!(*w.current_chord.lock().unwrap(), DetectedChord::default());
    }

